import{_ as t,o as a,c as i,a3 as s}from"./chunks/framework.CpLciM8b.js";const p=JSON.parse('{"title":"Test identity","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/test-identity.md","filePath":"concepts/test-identity.md","lastUpdated":1785494959000}'),r={name:"concepts/test-identity.md"};function o(n,e,l,d,h,c){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="test-identity" tabindex="-1">Test identity <a class="header-anchor" href="#test-identity" aria-label="Permalink to &quot;Test identity&quot;">​</a></h1><p>A test&#39;s value as telemetry depends on its history staying attached to it. If a test loses its identity every time a file moves or a title is tweaked, its flaky score resets to zero and the platform is blind exactly when a refactor is most likely to have introduced a regression. The <strong>test identity engine</strong> keeps one stable identity across those changes.</p><h2 id="why-a-naive-key-fails" tabindex="-1">Why a naive key fails <a class="header-anchor" href="#why-a-naive-key-fails" aria-label="Permalink to &quot;Why a naive key fails&quot;">​</a></h2><p>The obvious identity — <code>filePath + suite + title</code> — breaks the moment any of those change. Move <code>login.spec.ts</code> into a folder, rename <code>should log in</code> to <code>logs in</code>, or parameterize a test, and a naive key treats it as a brand-new test with no history. Real codebases do all three constantly.</p><h2 id="multi-level-resolution" tabindex="-1">Multi-level resolution <a class="header-anchor" href="#multi-level-resolution" aria-label="Permalink to &quot;Multi-level resolution&quot;">​</a></h2><p>Identity is resolved in levels, from strongest to weakest signal. The first level that matches wins, and history is stitched onto the existing identity:</p><ul><li><strong>L1 — exact.</strong> Same file path, suite, title, and parameters. The common case.</li><li><strong>L2 — moved.</strong> Same suite, title, and params but a different file path — the test moved. Matched by content so a file move keeps its history.</li><li><strong>L3 — renamed.</strong> Same file and suite but a changed title, matched by structural similarity so a rename does not fork the history.</li><li><strong>L4 — parameterized.</strong> Data-driven cases are grouped so a bucket of parameters rolls up to one logical test rather than fragmenting the score across every input.</li></ul><p>Because identity is computed <strong>server-side</strong> from <code>filePath + suite + title + params</code>, the resolution is identical no matter which reporter produced the run — Playwright, Vitest, Jest, or a JUnit upload. The reporters never send a fingerprint; they send the raw coordinates and the server decides.</p><h2 id="confidence-and-history-re-stitching" tabindex="-1">Confidence and history re-stitching <a class="header-anchor" href="#confidence-and-history-re-stitching" aria-label="Permalink to &quot;Confidence and history re-stitching&quot;">​</a></h2><p>Higher levels (moved, renamed) carry a confidence signal, and manual merge/split plus history re-stitching let a human correct the rare mismatch. Those controls are being expanded on the <a href="https://github.com/users/AKogut/projects/14" target="_blank" rel="noreferrer">roadmap</a>.</p><p>The full algorithm lives in the <a href="https://github.com/AKogut/flakemetry/wiki/Test-Identity-Engine" target="_blank" rel="noreferrer">Test Identity Engine wiki page</a>.</p>',11)])])}const u=t(r,[["render",o]]);export{p as __pageData,u as default};
